from __future__ import absolute_import

import logging
import time

from taf.selenium.core.common import PagePart

from taf.selenium.gnb.oam.coam.vdu.common.exceptions import FailedLoginException, ElementIsDisable
from taf.selenium.gnb.oam.coam.vdu.locators import Locator, Locator21b, Locator22R1, Locator22R2, Locator22R3, \
    Locator22R4, Locator23R4, Locator24R1, Locator24R2, Locator24R3, Locator25R1, Locator25R2, Locator25R3, \
    Locator26R1, Locator26R2, Locator24R4

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SupportedLocators(object):
    default = Locator
    locator_21b = Locator21b
    locator_22r1 = Locator22R1
    locator_22r2 = Locator22R2
    locator_22r3 = Locator22R3
    locator_22r4 = Locator22R4
    locator_23r4 = Locator23R4
    locator_24r1 = Locator24R1
    locator_24r2 = Locator24R2
    locator_24r3 = Locator24R3
    locator_24r4 = Locator24R4
    locator_25r1 = Locator25R1
    locator_25r2 = Locator25R2
    locator_25r3 = Locator25R3
    locator_26r1 = Locator26R1
    locator_26r2 = Locator26R2


class LoginPage(PagePart):
    def __init__(self, driver, version=None):
        super(LoginPage, self).__init__(driver)
        self.locator = getattr(SupportedLocators, 'locator_{}'.format(version), SupportedLocators.default)

    def enter_username(self, locator, username, timeout=60):
        self.insert_text_to_enabled_element(locator, username, timeout)

    def enter_password(self, locator, password, timeout=60):
        self.insert_text_to_enabled_element(locator, password, timeout)

    def click_login(self, locator, timeout=60):
        self.click_enabled_element(locator, timeout)


class CoamVDULoginPage(LoginPage):
    """
    A class manages login page, login function included.
    """

    def __init__(self, driver, version):
        super(CoamVDULoginPage, self).__init__(driver, version)
        self._driver = driver
        self._version = version

    def login(self, username, password, read_only_user, timeout=60):
        """
        Login into coam vdu WebEM as Web Element Manager.

        :param username: str, username
        :param password: str, password
        :param read_only_user: Boolean, read only check box enable
        :param timeout: int, timeout for the element be available to click
        """
        try:
            login_banner = None
            password_to_change_default_to = "Nokia@123"
            self.enter_username(self.locator.INPUT_USERNAME, username, timeout)
            self.enter_password(self.locator.INPUT_PASSWORD, password, timeout)
            if read_only_user:
                self.click_enabled_element(self.locator.READ_ONLY_USER_CHECK_BOX, timeout)
            self.click_login(self.locator.LOGIN_BUTTON, timeout)
            self._change_default_password_if_prompted(username=username, old_password=password,
                                                      new_password=password_to_change_default_to,
                                                      timeout=timeout)
            self._handling_wrong_password(username=username, new_password=password_to_change_default_to,
                                          timeout=timeout)
            login_banner = self.handling_legal_notice(timeout)
            self.read_only_conformation(read_only_user, timeout)
            if self.elements_is_visible(self.locator.CLOSE_BUTTON_XPATH, timeout=10):
                self.click_enabled_element(self.locator.CLOSE_BUTTON_XPATH, timeout)
            return login_banner
        except Exception:
            self.close_browser()
            raise FailedLoginException("Login unsuccessful hence exiting")

    def handling_legal_notice(self, timeout):
        if self.element_exists(self.locator.LEGAL_NOTICE_HEADER, 2):
            time.sleep(2)
            login_banner = self.get_text(self.locator.LEGAL_NOTICE_DATA, timeout)
            self.click_enabled_element(self.locator.LOGIN_CONFIRM_BUTTON, timeout)
            return login_banner
        return

    def read_only_conformation(self, read_only_user, timeout):
        if read_only_user:
            self.wait_for_visibility(self.locator.READ_ONLY_USER_BANNER, timeout)
            self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)

    def _change_default_password_if_prompted(self, username, old_password, new_password, timeout):
        if self.elements_is_visible(self.locator.PASSWORD_CHANGE_DIALOGUE_HEADER, 2):
            self.insert_text_to_enabled_element(self.locator.CURRENT_PASSWORD_INPUT, old_password, timeout)
            self.insert_text_to_enabled_element(self.locator.NEW_PASSWORD_INPUT, new_password, timeout)
            self.insert_text_to_enabled_element(self.locator.CONFORM_PASSWORD_INPUT, new_password, timeout)
            self.click_enabled_element(self.locator.SUBMIT_BUTTON, timeout)
            self.enter_username(self.locator.INPUT_USERNAME, username, timeout)
            self.enter_password(self.locator.INPUT_PASSWORD, new_password, timeout)
            self.click_login(self.locator.LOGIN_BUTTON, timeout)

    def _handling_wrong_password(self, username, new_password, timeout):
        if self.elements_is_visible(self.locator.AUTHENTICATION_FAILED, 2):
            self.enter_username(self.locator.INPUT_USERNAME, username, timeout)
            self.enter_password(self.locator.INPUT_PASSWORD, new_password, timeout)
            self.click_login(self.locator.LOGIN_BUTTON, timeout)


class LogoutPage(LoginPage):
    """
    A class manages logout page, logout function included.
    """

    def logout(self, timeout=60):
        """
        Logout from coam vdu web.

        :param int timeout: timeout for the element be available to click
        """
        try:
            self.click_enabled_element(self.locator.USER_COUNT_VIEW, timeout)
            self.click_enabled_element(self.locator.LOGOUT_BUTTON, timeout)
        except Exception:
            raise ElementIsDisable("Logout might have failed due change in ID's")
        finally:
            self.close_browser()
